WITH filtered AS (SELECT *, HOUR(paid_at) AS paid_at_hour, COALESCE(method, 'N/A') AS method_clean FROM payments WHERE method IS NOT NULL), prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) AS prev_paid_at FROM filtered), with_gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM prev_events), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT CASE WHEN is_new_session >= 1 THEN 'LARGE' ELSE 'SMALL' END AS is_new_session_tier, SORT_ARRAY(COLLECT_SET(method)) AS method_list, ROUND(SUM(paid_at_hour) / NULLIF(COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END), 0), 2) AS paid_at_hour_per_success, APPROX_PERCENTILE(paid_at_hour, 0.5) AS paid_at_hour_p50, SORT_ARRAY(COLLECT_SET(status)) AS status_list, COUNT(CASE WHEN method = 'promptpay' THEN 1 END) AS promptpay_count, GROUPING(CASE WHEN is_new_session >= 1 THEN 'LARGE' ELSE 'SMALL' END) AS gid FROM islands GROUP BY ROLLUP (CASE WHEN is_new_session >= 1 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY is_new_session_tier DESC NULLS LAST
